"use client";

import { useMemo } from "react";
import { Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import { type ExtrudePopElementId, extrudePopTimeline } from "./timeline";

export interface ExtrudePopProps {
  className?: string;
  width?: number;
  height?: number;
  letter?: string;
  fontFamily?: string;
  fontWeight?: number | string;
  fontSize?: number;
  basePosition?: [number, number];
  maxTextWidth?: number;
  minimaxRadius?: number;
  extrudeAngleDeg?: number;
  extrudeSteps?: number;
  extrudeStartFrame?: number;
  extrudeEndFrame?: number;
  bodyColor?: string;
  faceColor?: string;
  /**
   * Moves, trims or stretches the extrusion, by the ids in `./timeline`.
   * Frames on the scene timeline.
   */
  timing?: Timing<ExtrudePopElementId>;
}

export function ExtrudePop(props: ExtrudePopProps) {
  const {
    className,
    width = 1920,
    height = 1080,
    letter = "WIN",
    fontFamily = "'Helvetica Neue', Helvetica, Arial, sans-serif",
    fontWeight = 700,
    fontSize = 603,
    basePosition = [959.2, 752.5],
    maxTextWidth = 1660,
    minimaxRadius = 80,
    extrudeAngleDeg = -58.6,
    extrudeSteps = 200,
    bodyColor = "#e8192b",
    faceColor = "#ffffff",
    timing,
  } = props;
  const glide = useGlide();
  const frame = useSceneFrame();
  const { durationInFrames } = useSceneConfig();
  const tl = useTimeline(extrudePopTimeline, props, durationInFrames, timing);
  const extrude = tl.get("extrude");

  const fit = useMemo(() => {
    if (typeof document === "undefined") return 1;
    const ctx = document.createElement("canvas").getContext("2d");
    if (!ctx) return 1;
    ctx.font = `${fontWeight} ${fontSize}px ${fontFamily}`;
    const measured = ctx.measureText(letter).width;
    if (measured <= 0) return 1;
    return Math.min(1, maxTextWidth / measured);
  }, [letter, fontFamily, fontWeight, fontSize, maxTextWidth]);

  const fitFontSize = fontSize * fit;
  const fitRadius = minimaxRadius * fit;

  const radiusAt = (f: number) =>
    interpolate(f, [extrude.start, extrude.end], [0, fitRadius], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.16, 1, 0.3, 1),
    });
  const radius = radiusAt(frame);
  // The face travels 2 * radius; the ease-out tail is long, so this tests the
  // travel itself rather than the progress.
  const moving =
    Math.abs(radiusAt(frame + 1) - radius) * 2 > 1e-3 ||
    Math.abs(radius - radiusAt(frame - 1)) * 2 > 1e-3;

  const depth = radius * 2;

  const theta = (extrudeAngleDeg * Math.PI) / 180;
  const stepX = (depth * Math.sin(theta)) / extrudeSteps;
  const stepY = (depth * Math.cos(theta)) / extrudeSteps;

  const glyph = (fill: string, dx: number, dy: number, key: string) => (
    <text
      key={key}
      x={basePosition[0] + dx}
      y={basePosition[1] + dy}
      textAnchor="middle"
      fontFamily={fontFamily}
      fontWeight={fontWeight}
      fontSize={fitFontSize}
      fill={fill}
    >
      {letter}
    </text>
  );

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, overflow: "hidden" }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="xMidYMid meet"
        style={{ display: "block" }}
      >
        <g>
          {Array.from(
            { length: extrudeSteps + 1 },
            (_, i) => extrudeSteps - i,
          ).map((i) => glyph(bodyColor, stepX * i, stepY * i, `body-${i}`))}
        </g>
      </svg>
      {/* The face, stepped along by its x/y, is marked so it leans off the
          pixel grid while it moves. A marked drawing leans whole, so the face
          is a drawing of its own over the stack, with a body layer under it
          so no edge of it is left bare: across the whole stack the lean opens
          pinholes between layers, and a layer stepping inside a solid body
          shows nowhere. */}
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="xMidYMid meet"
        style={{ position: "absolute", inset: 0, transform: glide(moving) }}
      >
        {moving
          ? glyph(
              bodyColor,
              stepX * extrudeSteps,
              stepY * extrudeSteps,
              "under",
            )
          : null}
        {glyph(faceColor, stepX * extrudeSteps, stepY * extrudeSteps, "face")}
      </svg>
    </div>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The letters extruding out of the page. Frames on the 30 fps scene
// timeline. The ids are public: a saved `timing` prop refers to them.

export type ExtrudePopElementId = "extrude";

export interface ExtrudePopTimingProps {
  extrudeStartFrame?: number;
  extrudeEndFrame?: number;
}

const EXTRUDE_START = 0;
const EXTRUDE_END = 48;

export const extrudePopTimeline = defineTimeline<
  ExtrudePopElementId,
  ExtrudePopTimingProps
>(
  ({
    extrudeStartFrame = EXTRUDE_START,
    extrudeEndFrame = EXTRUDE_END,
  }): TimelineElement<ExtrudePopElementId>[] => [
    {
      id: "extrude",
      lane: "Letters",
      label: "Extrude",
      start: extrudeStartFrame,
      length: extrudeEndFrame - extrudeStartFrame,
    },
  ],
);
